import { isAbsolute, relative } from 'node:path';
import { compareSeverity, type Diagnostic, registry } from '@holotype/shared';
import { ExitCode } from '../exit-codes';
import type { RunComponent, RunReport } from '../run-report';

/*
 * Human output of a run (11 §3.1, §3.3): one header line, one line per component, where the
 * bundle went, warnings grouped by code, each error with its fix and help page, and the next
 * step. Plain text: no colour codes, so it reads the same in a terminal, a CI log and a file.
 */

/** Where a diagnostic's help page lives in the repository (generated by `pnpm diag:gen`). */
export function helpLink(code: string): string {
  return `docs/diagnostics/${code}.md`;
}

/** A path relative to `cwd` when it is inside it, else absolute. */
export function displayPath(path: string, cwd: string): string {
  const rel = relative(cwd, path);
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel) ? rel : path;
}

/** `8.1 KB`, `2.1 MB`. */
export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

const plural = (count: number, word: string) => `${count} ${word}${count === 1 ? '' : 's'}`;

const isError = (item: Diagnostic) => compareSeverity(item.severity, 'error') >= 0;

/** A diagnostic with its message, why, fix and help page; indented under `indent`. */
export function formatDiagnostic(item: Diagnostic, indent = ''): string[] {
  const where = item.sid === undefined ? '' : ` (${item.sid})`;
  const lines = [`${indent}✖ ${item.code}${where}  ${item.message}`];
  const reason = item.data?.reason;
  if (typeof reason === 'string' && reason !== '') lines.push(`${indent}  Why: ${reason}`);
  const remedy = registry.get(item.code)?.remedy;
  if (remedy !== undefined) lines.push(`${indent}  Fix: ${remedy}`);
  lines.push(`${indent}  Help: ${helpLink(item.code)}`);
  return lines;
}

function componentLine(component: RunComponent, width: number): string {
  const name = component.sid.padEnd(width);
  if (component.status === 'failed' || component.status === 'skipped') {
    const first = component.diagnostics.find(isError);
    return `  ✖ ${name}  ${first?.code ?? 'failed'} (see below)`;
  }
  const warnings = component.diagnostics.filter((item) => item.severity === 'warn').length;
  const props = Object.keys(component.properties).length;
  const mark = component.status === 'ok' ? '✔' : '!';
  const partial = component.status === 'partial' ? '  partial' : '';
  return `  ${mark} ${name}  ${plural(component.variants, 'variant')}  ${plural(props, 'prop')}  ${warnings} warn${partial}`;
}

function warningSummary(items: readonly Diagnostic[]): string[] {
  const counts = new Map<string, number>();
  for (const item of items) if (item.severity === 'warn') counts.set(item.code, (counts.get(item.code) ?? 0) + 1);
  if (counts.size === 0) return [];
  const sorted = [...counts].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return [
    `Warnings by code:  ${sorted.map(([code, count]) => `${code} ×${count}`).join(' · ')}`,
    ...sorted.map(([code]) => `  ${code}: ${helpLink(code)}`),
  ];
}

const NEXT_IMPORT = 'Next: in Figma, run Plugins ▸ Development ▸ Holotype, open Import file and pick';

/** The final output of `holotype capture` for people (11 §3.3 "capture summary"). */
export function formatCaptureSummary(report: RunReport, cwd: string): string {
  const lines: string[] = [];
  const { run } = report;
  const header = [`Holotype ${run.generator.version}`];
  if (run.storybook) header.push(`Storybook ${run.storybook.version} (${run.storybook.renderer})`);
  if (run.generator.chromium !== 'unknown') header.push(`Chromium ${run.generator.chromium}`);
  lines.push(header.join(' · '));

  const width = Math.max(0, ...report.components.map((component) => component.sid.length));
  for (const component of report.components) lines.push(componentLine(component, width));

  if (report.output) {
    lines.push(`Bundle: ${displayPath(report.output.path, cwd)} (${formatBytes(report.output.bytes)})`);
  }
  const all = [...report.diagnostics, ...report.components.flatMap((component) => component.diagnostics)];
  lines.push(...warningSummary(all));
  const errors = all.filter(isError);
  if (errors.length > 0) {
    lines.push(errors.length === 1 ? 'Error:' : `Errors (${errors.length}):`);
    for (const item of errors) lines.push(...formatDiagnostic(item, '  '));
  }
  if (report.failure) {
    lines.push(`✖ ${report.failure.message}`, `  Fix: ${report.failure.hint}`);
  }
  lines.push(...nextStep(report, cwd));
  return `${lines.join('\n')}\n`;
}

function nextStep(report: RunReport, cwd: string): string[] {
  const code = report.run.exitCode;
  if (report.output && (code === ExitCode.Ok || code === ExitCode.Errors || code === ExitCode.QualityGate)) {
    if (report.output.kind === 'dir') {
      return ['Next: the Figma plugin imports zip files; run again with --out <name>.holotype.zip to get one.'];
    }
    return [`${NEXT_IMPORT} ${displayPath(report.output.path, cwd)}.`];
  }
  switch (code) {
    case ExitCode.Usage:
      return ['Next: fix the flags or the config above, then run the command again (holotype capture --help).'];
    case ExitCode.StorybookUnreachable:
      return ['Next: build Storybook (storybook build) or start it, then pass --storybook <dir|url>.'];
    case ExitCode.Browser:
      return ['Next: install the browser as shown above, then run the command again.'];
    case ExitCode.Interrupted:
      return ['Interrupted. Nothing was written.'];
    default:
      return ['Next: fix the errors above, then run the command again.'];
  }
}

/** One progress line for stderr. */
export function formatProgress(text: string): string {
  return `${text}\n`;
}
